insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (196187, 196187, 'smoking-behind-the-supermarket-with-you', 'Smoking Behind the Supermarket with You', 'Super no Ura de Yani Suu Futari', 'Sasaki is an overworked salaryman drifting through the corporate grind, sustained by cigarettes and the cheerful service and smile of Yamada, the clerk at his favorite supermarket. But one night after a grueling shift, he arrives late to find Yamada nowhere to be seen. With nowhere left to smoke, his spirits sink—until a pierced young woman calls out to him: “You can smoke here.” (Source: Crunchyroll) Note: Episodes 1-6 had an early release by ABEMA and Crunchyroll on June 3rd, 2026 in a mini-episode batch format that splits 6 episodes into 12, ahead of the TV broadcast which started on July 10th, 2026.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/196187-Z9dV6uotmKjM.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx196187-0dgFi2CPp3xn.jpg', 'TV', 'FINISHED', 2026, 12, 24, 81, 81000, 'R', 'SUB', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (180136, 180136, 'the-exiled-heavy-knight-knows-how-to-game-the-system', 'The Exiled Heavy Knight Knows How to Game the System', 'Tsuihou Sareta Tensei Juukishi wa Game Chishiki de Musou Suru', 'Born into a prestigious family of master swordsmen, Elymas Edvaughn’s future shatters when he awakens the so-called “defective” Heavy Knight class. Disowned and cast out, he regains memories of another life—and realizes this world mirrors a VR game he once mastered. Armed with knowledge no one else possesses, he sets out to rewrite his fate and prove the strength of the “weakest” class. (Source: Crunchyroll)', null, 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx180136-gtMTCRlOD4OE.jpg', 'TV', 'RELEASING', 2026, 26, 24, 67, 67000, 'PG-13', 'HD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (189046, 189046, 're-zero-starting-life-in-another-world-season-4', 'Re:ZERO -Starting Life in Another World- Season 4', 'Re:Zero kara Hajimeru Isekai Seikatsu 4th Season', 'In the deadly battle at Priestella, Subaru and his allies emerged victorious, but at great cost. As Subaru searches for a way to save Rem, Crusch, and Julius, he learns of a "wise woman," Shaula, an all-seeing being said to possess every form of knowledge, who resides at the Pleiades Watchtower. Subaru and his crew must brave the uncharted Auguria Dunes to reclaim what was lost. (Source: Crunchyroll) Note: Lucca Comics & Games pre-screened episode 1 early on November 1, 2025, prior to the Japanese television broadcast on July 8th, 2026.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/189046-MDk2CaVuRWpb.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx189046-yaHWtS5FII46.jpg', 'TV', 'RELEASING', 2026, 19, 24, 90, 90000, 'PG-13', 'FHD', true, true, true, true, 4);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21, 21, 'one-piece', 'ONE PIECE', 'ONE PIECE', 'Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King. Enter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece. *This includes the following special episodes: - Chopperman to the Rescue! Protect the TV Station by the Shore! (Episode 336) - The Strongest Tag-Team! Luffy and Toriko''s Hard Struggle! (Episode 492) - Team Formation! Save Chopper (Episode 542) - History''s Strongest Collaboration vs. Glutton of the Sea (Episode 590) - 20th Anniversary! Special Romance Dawn (Episode 907)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21-wf37VakJmZqs.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21-ELSYx3yMPcKM.jpg', 'TV', 'RELEASING', 1999, 0, 24, 87, 87000, 'PG-13', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (194829, 194829, 'from-old-country-bumpkin-to-master-swordsman-ii', 'From Old Country Bumpkin to Master Swordsman II', 'Katainaka no Ossan, Kensei ni Naru II', 'Beryl Gardenant, a swordmaster from the countryside, is settling into his new life as a special instructor for the Royal Order of Knights and the guardian of an orphan. A peaceful life is not in the cards, however, and Beryl is confronted with new obstacles. At the magic institute, in his hometown, at the kingdom''s border, away in a foreign land... It''s time for Beryl to face new battles. (Source: Prime Video)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/194829-mAQpjlKYA8c2.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx194829-bZKwhfo60EuF.jpg', 'TV', 'FINISHED', 2026, 12, 23, 71, 71000, 'G', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (135865, 135865, 'saga-of-tanya-the-evil-season-2', 'Saga of Tanya the Evil Season 2', 'Youjo Senki II', 'The second season of Youjo Senki.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/135865-Ws3e7BhBkFxd.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx135865-T7XIPMAbqcxN.png', 'TV', 'FINISHED', 2026, 12, 24, 80, 80000, 'PG', '4K', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (178789, 178789, 'mushoku-tensei-jobless-reincarnation-season-3', 'Mushoku Tensei: Jobless Reincarnation Season 3', 'Mushoku Tensei III: Isekai Ittara Honki Dasu', 'The third season of Mushoku Tensei: Isekai Ittara Honki Dasu.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/178789-9nHWmoRLlcLu.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx178789-hNXjKFzUq7mk.jpg', 'TV', 'RELEASING', 2026, 14, 24, 85, 85000, 'G', '4K', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (159309, 159309, 'trapped-in-a-dating-sim-the-world-of-otome-games-is-tough-for-mobs-season-2', 'Trapped in a Dating Sim: The World of Otome Games is Tough for Mobs Season 2', 'Otomege Sekai wa Mob ni Kibishii Sekai desu 2', 'Office worker Leon has just been thrust into an otome game where women hold all the power. His only tool for survival is the knowledge gained from playing this game in his past life. But after befriending the heroine and villainess, and making a name for himself, his choices begin to warp the story beyond what he knows. Now, Leon is dragged into a conspiracy that could shake the entire kingdom. (Source: Crunchyroll)', null, 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx159309-wRfh9O1odrDJ.jpg', 'TV', 'FINISHED', 2026, 12, 24, 69, 69000, 'G', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (207141, 207141, 'chainsmoker-cat', 'Chainsmoker Cat', 'Yani Neko', 'Yani is a catgirl with a seriously bad smoking habit. She smokes so much that her apartment smells like ash and is littered with cigarette butts—and plenty of other trash! Every time she tries to quit, she becomes weak to the cravings and gives in almost instantly. Will she ever get her life together, or is she doomed to live as a chainsmoking slob forever? (Source: Seven Seas Entertainment)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/207141-MvHAS2YVfJzL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx207141-h5q5KJPd6vaX.jpg', 'TV', 'FINISHED', 2026, 12, 24, 67, 67000, 'PG-13', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (182205, 182205, 'that-time-i-got-reincarnated-as-a-slime-season-4', 'That Time I Got Reincarnated as a Slime Season 4', 'Tensei Shitara Slime Datta Ken 4th Season', 'Demon Lord Rimuru''s dream of creating an alliance between humans and monsters takes a step closer to being realized. As Tempest continues to prosper, Granville Rozzo and his granddaughter, Maribel Rozzo, clash with Demon Lord Rimuru over their plan to protect mankind by ruling over them. Meanwhile, in El Dorado, Demon Lord Leon works toward goals of his own. The awakening of a new Hero draws near! (Source: Crunchyroll News)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182205-fRUoKv6f2JAq.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx182205-q2AeO1owuQbO.jpg', 'TV', 'RELEASING', 2026, 24, 24, 83, 83000, 'PG', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (269, 269, 'bleach', 'Bleach', 'BLEACH', 'Ichigo Kurosaki is a rather normal high school student apart from the fact he has the ability to see ghosts. This ability never impacted his life in a major way until the day he encounters the Shinigami Kuchiki Rukia, who saves him and his family''s lives from a Hollow, a corrupt spirit that devours human souls. Wounded during the fight against the Hollow, Rukia chooses the only option available to defeat the monster and passes her Shinigami powers to Ichigo. Now forced to act as a substitute until Rukia recovers, Ichigo hunts down the Hollows that plague his town.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/269-08ar2HJOUAuL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx269-d2GmRkJbMopq.png', 'TV', 'FINISHED', 2004, 366, 24, 79, 79000, 'G', '4K', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (198946, 198946, 'clevatess-season-2', 'Clevatess Season 2', 'Clevatess II: Majuu no Ou to Itsuwari no Yuusha Denshou', 'The war is over, but General Drel''s secrets remain. As visitors from Hiden, Boelate, and Eslinn converge on Solsein, Boelate''s divine academy, the search for Drel''s hidden room begins. Among those drawn into the mystery is Klen, now serving as Luna''s magic teacher. But what truth lies at the heart of Drel''s secret? (Source: Crunchyroll)', null, 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx198946-IGXmbqBEYRYD.jpg', 'TV', 'RELEASING', 2026, 13, 24, 76, 76000, 'PG-13', 'FHD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (203880, 203880, 'dara-san-of-the-reiwa-era', 'Dara-san of the Reiwa Era', 'Reiwa no Dara-san', 'After venturing into a restricted, treacherous mountain forest, siblings Hinata and Kaoru meet a terrifying serpent god and become besties! Despite her initially scary appearance, the self-named “god of misfortune” is awkward, lonely, and surprisingly easy to talk to. This is the tale of an unexpected friendship, and the many comedic, heartfelt adventures that ensue. (Source: Crunchyroll)', null, 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx203880-lnruKftb27Nr.png', 'TV', 'FINISHED', 2026, 13, 24, 66, 66000, 'PG', 'HD', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (195600, 195600, 'daemons-of-the-shadow-realm', 'Daemons of the Shadow Realm', 'Yomi no Tsugai', 'In a remote mountain village under the watchful eyes of two stone guardians, the young Yuru contentedly lives off the land while staying close to the only family he has left—Asa, his precious twin sister. Asa, meanwhile, carries out a mysterious “duty” on behalf of the village while locked in a cage. Why is Asa a prisoner? And what other secrets does Yuru’s otherwise idyllic home hide? (Source: Square Enix)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/195600-UxHvDXwzJxlP.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx195600-moI0UFArtOme.jpg', 'TV', 'FINISHED', 2026, 24, 24, 78, 78000, 'PG', 'HD', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (202269, 202269, 'love-unseen-beneath-the-clear-night-sky', 'Love Unseen Beneath the Clear Night Sky', 'Toumei na Yoru ni Kakeru Kimi to, Me ni Mienai Koi wo Shita.', 'Kakeru Sorano, a quiet university freshman who avoids others, meets Koharu Fuyutsuki, a blind girl who faces the world with quiet brightness. When she says, “I want to see fireworks someday,” something in Kakeru shifts. As they grow closer through small moments and shared loneliness, he searches for a way to make her wish come true. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/202269-u0PTTsiKwrVL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202269-7KNj8s2fSsJJ.jpg', 'TV', 'FINISHED', 2026, 12, 24, 83, 83000, 'G', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (187538, 187538, 'black-torch', 'BLACK TORCH', 'BLACK TORCH', 'Jirou Azuma is no average high schooler. A descendant of ninjas and trained in the ancient warrior art of the shinobi, Jirou is also able to talk with animals. After a mysterious encounter with an injured cat named Ragou, Jirou discovers the feline is actually the legendary Black Star of Doom! Joined by the Bureau of Espionage, they fight off swarms of mononoke lying in wait to exploit Ragou’s powers. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187538-287evzCezNl0.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187538-fXVXKYUA3VV6.jpg', 'TV', 'FINISHED', 2026, 12, 24, 69, 69000, 'NC-17', 'FHD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (187260, 187260, 'i-want-to-love-you-till-your-dying-day', 'I Want to Love You Till Your Dying Day', 'Kimi ga Shinu made Koi wo Shitai', 'At the mysterious orphanage where Sheena lives, death is nothing new to its residents—girls who no longer have families of their own, who are raised as weapons of war, taught to kill and take the lives of others without batting an eye. Everyone, that is, except Sheena, who wishes for nothing more than the growing conflict around her to end. On the night of her roommate''s death, Sheena meets a strange girl covered in blood, who smiles despite the turmoil surrounding them. The next day, the girl appears as a new student in Sheena''s class and introduces herself as Mimi. Initially thought to be a school myth, there are now whispers in the orphanage''s halls that Mimi is their secret weapon—an immortal who cannot die. When Mimi is later assigned as Sheena''s new roommate, Sheena''s world grows even more complicated when she begins living with someone who loves and welcomes death, when all Sheena wants to do is stop it… (Source: Kodansha USA)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187260-HMkLPy3ZvzW1.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187260-WW5RBa5NINRP.jpg', 'TV', 'RELEASING', 2026, 13, 24, 74, 74000, 'PG', 'HD', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (97940, 97940, 'black-clover', 'Black Clover', 'Black Clover', 'In a world where magic is everything, Asta and Yuno are both found abandoned at a church on the same day. While Yuno is gifted with exceptional magical powers, Asta is the only one in this world without any. At the age of fifteen, both receive grimoires, magic books that amplify their holder’s magic. Asta’s is a rare Grimoire of Anti-Magic that negates and repels his opponent’s spells. Being opposite but good rivals, Yuno and Asta are ready for the hardest of challenges to achieve their common dream: to be the Wizard King. Giving up is never an option! (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97940-1URQdQ4U1a0b.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97940-fyh8o7gNbha0.png', 'TV', 'FINISHED', 2017, 170, 24, 79, 79000, 'PG', 'HD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (1735, 1735, 'naruto-shippuden', 'Naruto: Shippuden', 'NARUTO: Shippuuden', 'Naruto: Shippuuden is the continuation of the original animated TV series Naruto. The story revolves around an older and slightly more matured Uzumaki Naruto and his quest to save his friend Uchiha Sasuke from the grips of the snake-like Shinobi, Orochimaru. After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work, though it will not be easy, as he has amassed a few (more dangerous) enemies, in the likes of the shinobi organization; Akatsuki. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1735.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1735-kGfVm0YqCPcu.png', 'TV', 'FINISHED', 2007, 500, 23, 82, 82000, 'PG', 'SUB', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (185542, 185542, 'skeleton-knight-in-another-world-season-2', 'Skeleton Knight in Another World Season 2', 'Gaikotsu Kishi-sama, Tadaima Isekai e Odekakechuu II', 'Arc returns! After waking to find he''s become a Skeleton Knight in his favorite fantasy video game, Arc, Ariane, Chiyome, and Ponta band together to take on evil. Before Arc''s search for a cure to his skeletal condition continues, he must face a dogmatic leader, Count Hilk, to free oppressed elves and beasts. A new chapter begins as the Skeleton Knight fights to make his new world a better place. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185542-v15vqOvUWSF5.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185542-6a9LCWlLHa0T.jpg', 'TV', 'FINISHED', 2026, 12, 24, 65, 65000, 'R', 'FHD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (199111, 199111, 'grand-blue-dreaming-season-3', 'Grand Blue Dreaming Season 3', 'Grand Blue Season 3', 'Iori''s college shenanigans head overseas! Just as he''s finally starting to get the hang of university life, crashing at his uncle''s dive shop while balancing the booze-fueled antics of his diving club, Iori''s cousin enlists him to help run a new dive shop in Palau. Between crystal-clear dives and his diving group that can''t resist partying it up and stripping down, Iori''s in for a wild summer. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/199111-Z8y9awn2Zb6v.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199111-gBSuBG61ElcW.jpg', 'TV', 'FINISHED', 2026, 12, 24, 82, 82000, 'PG-13', 'SUB', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (200637, 200637, 'the-100-girlfriends-who-really-really-really-really-really-love-you-season-3', 'The 100 Girlfriends Who Really, Really, Really, Really, REALLY Love You Season 3', 'Kimi no Koto ga Dai Dai Dai Dai Daisuki na 100-nin no Kanojo 3rd Season', 'The third season of Kimi no Koto ga Dai Dai Dai Dai Daisuki na 100-nin no Kanojo.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/200637-q9mehOFbbCgT.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx200637-QLR5uv9SbQ69.jpg', 'TV', 'FINISHED', 2026, 12, 24, 80, 80000, 'R', '4K', false, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (204466, 204466, 'kaiju-girl-caramelise', 'KAIJU GIRL CARAMELISE', 'Otome Kaijuu Caraméliser', 'Kuroe Akaishi just wants a normal high school life—but that’s impossible with a rare condition that turns her into a giant kaiju whenever her emotions spike! Things get even worse when she falls for Arata Minami, the most popular boy in class. Now every blush, heartbeat, and crush could trigger a monster transformation. Can Kuroe survive high school love before it destroys everything around her?! (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/204466-cpbNGN9qHrGP.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx204466-vXMvIs4VOoQd.png', 'TV', 'FINISHED', 2026, 12, 24, 75, 75000, 'PG-13', 'FHD', true, true, true, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (5114, 5114, 'fullmetal-alchemist-brotherhood', 'Fullmetal Alchemist: Brotherhood', 'Hagane no Renkinjutsushi: FULLMETAL ALCHEMIST', '"In order for something to be obtained, something of equal value must be lost." Alchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist. Three years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. In between finding a serial killer and racing against time, Edward and Alphonse must ask themselves if what they are doing will make them human again... or take away their humanity. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5114-q0V5URebphSG.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5114-nSWCgQlmOMtj.jpg', 'TV', 'FINISHED', 2009, 64, 25, 90, 90000, 'G', 'FHD', true, true, true, true, 6);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21856, 21856, 'my-hero-academia-season-2', 'My Hero Academia Season 2', 'Boku no Hero Academia 2', 'Taking off right after the last episode of the first season. The school is temporarily closed due to security. When U.A. restarts, it is announced that the highly anticipated School Sports Festival will soon be taking place. All classes: Hero, Support, General and Business will be participating. Tournaments all round will decide who is the top Hero in training.(Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21856-wtSHgeHFmzdG.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21856-gutauxhWAwn6.png', 'TV', 'FINISHED', 2017, 25, 24, 79, 79000, 'PG-13', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (110277, 110277, 'attack-on-titan-final-season', 'Attack on Titan Final Season', 'Shingeki no Kyojin: The Final Season', 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars? (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/110277-iuGn6F5bK1U1.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx110277-sKUNXAsWMNFw.jpg', 'TV', 'FINISHED', 2021, 16, 24, 87, 87000, 'R', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (127230, 127230, 'chainsaw-man', 'Chainsaw Man', 'Chainsaw Man', 'Denji is a teenage boy living with a Chainsaw Devil named Pochita. Due to the debt his father left behind, he has been living a rock-bottom life while repaying his debt by harvesting devil corpses with Pochita. One day, Denji is betrayed and killed. As his consciousness fades, he makes a contract with Pochita and gets revived as "Chainsaw Man" — a man with a devil''s heart. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/127230-o8IRwCGVr9KW.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx127230-DdP4vAdssLoz.png', 'TV', 'FINISHED', 2022, 12, 25, 83, 83000, 'PG', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (101759, 101759, 'the-promised-neverland', 'The Promised Neverland', 'Yakusoku no Neverland', 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing. (Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101759-MhlCoeqnODso.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101759-8UR7r9MNVpz2.jpg', 'TV', 'FINISHED', 2019, 12, 23, 83, 83000, 'G', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20755, 20755, 'assassination-classroom', 'Assassination Classroom', 'Ansatsu Kyoushitsu', 'The students of class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20755-D4ipww9U8YkC.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20755-dWrhs569YGUO.jpg', 'TV', 'FINISHED', 2015, 22, 23, 79, 79000, 'PG', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21507, 21507, 'mob-psycho-100', 'Mob Psycho 100', 'Mob Psycho 100', 'The story revolves around "Mob," a boy who will explode if his emotional capacity reaches 100%. This boy with psychic powers earned his nickname "Mob" because he does not stand out among other people. He keeps his psychic powers bottled up so he can live normally, but if his emotional level reaches 100, something will overwhelm his entire body. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21507-Qx8bGsLXUgLo.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21507-6YUSbh2m0N1p.jpg', 'TV', 'FINISHED', 2016, 12, 24, 84, 84000, 'R', 'SUB', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21355, 21355, 're-zero-starting-life-in-another-world', 'Re:ZERO -Starting Life in Another World-', 'Re:Zero kara Hajimeru Isekai Seikatsu', 'In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since. (Source: Anime News Network) Notes: - The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode. - In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21355-f9SjOfEJMk5P.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21355-wRVUrGxpvIQQ.jpg', 'TV', 'FINISHED', 2016, 25, 25, 81, 81000, 'PG', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20665, 20665, 'your-lie-in-april', 'Your lie in April', 'Shigatsu wa Kimi no Uso', 'Piano prodigy Arima Kousei dominated the competition and all child musicians knew his name. But after his mother, who was also his instructor, passed away, he had a mental breakdown while performing at a recital. This resulted in him no longer being able to hear the sound of his piano playing. Two years later, Kousei hasn’t touched the piano and views the world without any flair or color. He was content at living out his life with his good friends Tsubaki and Watari until, one day, a girl changed everything. Miyazono Kaori is a pretty, free spirited violinist whose playing style reflects her personality. Kaori helps Kousei return to the music world and show that it should be free and mold breaking unlike the structured and rigid style Kousei was used to.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20665-j4kSsfhfkM24.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20665-TLgkL8T8IRFd.png', 'TV', 'FINISHED', 2014, 22, 23, 84, 84000, 'PG', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (104578, 104578, 'attack-on-titan-season-3-part-2', 'Attack on Titan Season 3 Part 2', 'Shingeki no Kyojin Season 3 Part 2', 'The battle to retake Wall Maria begins now! With Eren’s new hardening ability, the Scouts are confident they can seal the wall and take back Shiganshina District. If they succeed, Eren can finally unlock the secrets of the basement—and the world. But danger lies in wait as Reiner, Bertholdt, and the Beast Titan have plans of their own. Could this be humanity’s final battle for survival? (Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104578-z7SadpYEuAsy.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104578-k61nx3LPjvgd.jpg', 'TV', 'FINISHED', 2019, 10, 24, 89, 89000, 'NC-17', 'FHD', true, false, false, true, 8);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21234, 21234, 'erased', 'ERASED', 'Boku dake ga Inai Machi', 'Satoru Fujinuma is a 29 year old manga artist struggling to make a name for himself following his debut. But, that was not the only thing in his life that Satoru was feeling frustrated about… He has a unique supernatural ability of being forced to prevent deaths and catastrophes by being sent back in time before the incident occurred, repeating time until the accident is prevented. One day, he gets involved in an accident that has him framed as a murderer. Desperate to save the victim, he sends himself back in time only to find himself as a grade-schooler one month before fellow classmate Kayo Hinazuki went missing. Satoru now embarks on a new quest: to save Kayo and solve the mystery behind her disappearance.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21234-7lfSSPoMmwr2.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21234-XmqW39aQ9o7O.jpg', 'TV', 'FINISHED', 2016, 12, 23, 81, 81000, 'G', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (100166, 100166, 'my-hero-academia-season-3', 'My Hero Academia Season 3', 'Boku no Hero Academia 3', 'Summer is here, and the heroes of Class 1-A and 1-B are in for the toughest training camp of their lives! A group of seasoned pros pushes everyone''s Quirks to new heights as the students face one overwhelming challenge after another. Braving the elements in this secret location becomes the least of their worries when routine training turns into a critical struggle for survival.(Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100166-k7RXwN5vZg0r.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100166-jUCZYbzn2XLw.jpg', 'TV', 'FINISHED', 2018, 25, 24, 79, 79000, 'PG-13', 'FHD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (9253, 9253, 'steins-gate', 'Steins;Gate', 'Steins;Gate', 'Self-proclaimed mad scientist Okabe Rintarou lives in a small room in Akihabara, where he invents "future gadgets" with fellow lab members Shiina Mayuri, his air-headed childhood friend, and Hashida Itaru, an otaku hacker. The three pass the time by tinkering with their latest creation, a "Phone Microwave" that can be controlled through text messages. The lab members soon face a string of mysterious incidents that lead to a game-changing discovery: the Phone Microwave can send emails to the past and thus alter history. Adapted from the critically acclaimed visual novel by 5pb. and Nitroplus, Steins;Gate takes Okabe to the depths of scientific theory and human despair as he faces the dire consequences of changing the past.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n9253-JIhmKgBKsWUN.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9253-tIUXF2gfU8Sg.jpg', 'TV', 'FINISHED', 2011, 24, 24, 89, 89000, 'NC-17', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20464, 20464, 'haikyu', 'HAIKYU!!', 'Haikyuu!!', 'Inspired after watching a volleyball ace nicknamed "Little Giant" in action, small-statured Shouyou Hinata revives the volleyball club at his middle school. The newly-formed team even makes it to a tournament; however, their first match turns out to be their last when they are brutally squashed by the "King of the Court," Tobio Kageyama. Hinata vows to surpass Kageyama, and so after graduating from middle school, he joins Karasuno High School''s volleyball team—only to find that his sworn rival, Kageyama, is now his teammate. Thanks to his short height, Hinata struggles to find his role on the team, even with his superior jumping power. Surprisingly, Kageyama has his own problems that only Hinata can help with, and learning to work together appears to be the only way for the team to be successful. Based on Haruichi Furudate''s popular shounen manga of the same name, Haikyuu!! is an exhilarating and emotional sports comedy following two determined athletes as they attempt to patch a heated rivalry in order to make their high school volleyball team the best in Japan. [Written by MAL Rewrite]', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20464-PpYjO9cPN1gs.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20464-ooZUyBe4ptp9.png', 'TV', 'FINISHED', 2014, 25, 24, 83, 83000, 'G', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (101291, 101291, 'rascal-does-not-dream-of-bunny-girl-senpai', 'Rascal Does Not Dream of Bunny Girl Senpai', 'Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai', 'There''s a rumor about a mysterious phenomenon called "puberty syndrome." For example, Sakuta Azusagawa is a high school student who suddenly sees a bunny girl appear in front of him. The girl is actually a girl named Mai Sakurajima, who is Sakuta''s upperclassman who is also a famous actress who has gone on hiatus from the entertainment industry. For some reason, the people around Mai cannot see her bunny-girl figure. Sakuta sets out to solve this mystery, and as he spends time with Mai, he learns her secret feelings. Other heroines who have "puberty syndrome" start to appear in front of Sakuta. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n101291-fqIUvQ6apEtD.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101291-wfEdgPqtfU0l.jpg', 'TV', 'FINISHED', 2018, 13, 25, 81, 81000, 'PG-13', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20954, 20954, 'a-silent-voice', 'A Silent Voice', 'Koe no Katachi', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends. (Source: Eleven Arts)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20954-f30bHMXa5Qoe.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20954-sYRfE5jQRtSB.jpg', 'MOVIE', 'FINISHED', 2016, 1, 130, 88, 88000, 'G', 'FHD', true, false, false, true, 3);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21519, 21519, 'your-name', 'Your Name.', 'Kimi no Na wa.', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture. One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another. Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21519-1ayMXgNlmByb.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21519-SUo3ZQuCbYhJ.png', 'MOVIE', 'FINISHED', 2016, 1, 107, 85, 85000, 'G', 'SUB', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (112151, 112151, 'demon-slayer-kimetsu-no-yaiba-the-movie-mugen-train', 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 'Kimetsu no Yaiba: Mugen Ressha-hen', 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112151-eHCBz19nf2yC.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112151-1qlQwPB1RrJe.png', 'MOVIE', 'FINISHED', 2020, 1, 117, 84, 84000, 'PG-13', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (199, 199, 'spirited-away', 'Spirited Away', 'Sen to Chihiro no Kamikakushi', 'On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/199-Sm2RU5PSqw7T.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199-sWefXJvXkDOb.jpg', 'MOVIE', 'FINISHED', 2001, 1, 125, 86, 86000, 'G', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (131573, 131573, 'jujutsu-kaisen-0', 'JUJUTSU KAISEN 0', 'Jujutsu Kaisen 0', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him? (Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/131573-3veuVz5p0z2I.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131573-rpl82vDEDRm6.jpg', 'MOVIE', 'FINISHED', 2021, 1, 105, 83, 83000, 'NC-17', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (99750, 99750, 'i-want-to-eat-your-pancreas', 'I Want to Eat Your Pancreas', 'Kimi no Suizou wo Tabetai', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret. Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change. (Source: Aniplex USA)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99750-KPFW2Jv03b2B.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99750-pNyly9d3MEgV.jpg', 'MOVIE', 'FINISHED', 2018, 1, 108, 84, 84000, 'PG', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (431, 431, 'howl-s-moving-castle', 'Howl‘s Moving Castle', 'Howl no Ugoku Shiro', 'Sophie, a quiet girl working in a hat shop, finds her life thrown into turmoil when she is literally swept off her feet by a handsome but mysterious wizard named Howl. The vain and vengeful Witch of the Waste, jealous of their friendship, puts a spell on Sophie. In a life-changing adventure, Sophie climbs aboard Howl''s magnificent flying castle and enters a magical world on a quest to break the spell. (Source: Disney)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/431-fLBlvTgdqLCz.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx431-o8Lj3XkjHm2k.jpg', 'MOVIE', 'FINISHED', 2004, 1, 119, 85, 85000, 'PG-13', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (106286, 106286, 'weathering-with-you', 'Weathering With You', 'Tenki no Ko', 'High school student Hodaka leaves his home on an isolated island and moves to Tokyo, but he immediately becomes broke. He lives his days in isolation, but finally finds a job as a writer for a shady occult magazine. After he starts his job, the weather has been rainy day after day. In a corner of the crowded and busy city, Hodaka meets a young woman named Hina. Due to certain circumstances, Hina and her younger brother live together, but have a cheerful and sturdy life. Hina also has a certain power: the power to stop the rain and clear the sky. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/106286-3oKwiwjd7Wkm.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106286-5COcpd0J9VbL.png', 'MOVIE', 'FINISHED', 2019, 1, 115, 81, 81000, 'PG-13', 'FHD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (164, 164, 'princess-mononoke', 'Princess Mononoke', 'Mononoke-hime', 'A calm village residing in the mountains comes under attack from a demon-possessed boar one day. Ashitaka, a young man and prince of the tribe, engages the creature in an attempt to save his village. During the battle, the boar bites him on the arm, leaving it blackened and cursed. Following his village''s traditions, Ashitaka is exiled and becomes a wanderer, looking for a solution to the curse before it engulfs him. Iron Town is a fortress under the leadership of Lady Eboshi. Through the clearing of the surrounding forests, Iron Town produces large amounts of Ironsand, used for gunpowder and other machinery. However, because of the forests destruction, nearby animal clans seek revenge led by a human girl of the Wolf clan called San. When Ashitaka comes to Iron Town, he discovers the area consumed in battle. Horrified, he attempts to create peace and befriend the Wolf Clan. However, after the forest''s eradication and the ongoing war between Human and Beast, will the Spirit of the Forest be forgiving and accept Ashitaka''s request to expel his curse? [Written by MAL Rewrite]', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/164-Aj6MINy7VTfs.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx164-ySuGzCWVw2cL.jpg', 'MOVIE', 'FINISHED', 1997, 1, 134, 85, 85000, 'G', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (523, 523, 'my-neighbor-totoro', 'My Neighbor Totoro', 'Tonari no Totoro', 'Follow the adventures of Satsuki and her four-year-old sister Mei when they move into a new home in the countryside. To their delight they discover that their new neighbor is a mysterious forest spirit called Totoro who can be seen only through the eyes of a child. Totoro introduces them to extraordinary characters, including a cat that doubles as a bus, takes them on a journey through the wonders of nature. (Source: Disney)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/523-rl12Q0av1fCr.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx523-fErBvxOHP7IX.jpg', 'MOVIE', 'FINISHED', 1988, 1, 86, 81, 81000, 'NC-17', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (104157, 104157, 'rascal-does-not-dream-of-a-dreaming-girl', 'Rascal Does Not Dream of a Dreaming Girl', 'Seishun Buta Yarou wa Yumemiru Shoujo no Yume wo Minai', 'In Fujisawa, where the skies are bright and the seas glisten, Sakuta Azusagawa is in his second year of high school. His blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted with the appearance of his first crush, Shouko Makinohara. For reasons unknown, he encounters two Shouko''s: one in middle school and another who has become an adult. As Sakuta finds himself helplessly living with the Shouko''s, the adult Shouko leads him around by the nose, causing a huge rift in his relationship with Mai. In the midst of all of this, he discovers that the middle school Shouko is suffering from a grave illness and his scar begins to throb... (Source: Aniplex USA)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104157-PS7tfPpvJKhk.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104157-rk99XI56PaIC.jpg', 'MOVIE', 'FINISHED', 2019, 1, 90, 84, 84000, 'R', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (32, 32, 'neon-genesis-evangelion-the-end-of-evangelion', 'Neon Genesis Evangelion: The End of Evangelion', 'Shin Seiki Evangelion Movie: Air / Magokoro wo, Kimi ni', 'NERV faces a brutal attack from SEELE, but with Asuka in a coma, and Shinji in a nervous breakdown, things soon turn into the surreal. This movie provides a concurrent ending to the final two episodes of the show Neon Genesis Evangelion. (Source: IMDb)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n32-BH9yHJBQqeOa.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx32-5JYsv0wc122I.jpg', 'MOVIE', 'FINISHED', 1997, 1, 87, 85, 85000, 'R', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (184356, 184356, 'tomb-raider-king', 'Tomb Raider King', 'Dogul Wang', 'Chaos ensues overnight when mysterious tombs suddenly surface, filled with divine relics granting overwhelming power, triggering a global power struggle to claim them for dominion. Among the havoc, a raider, Jooheon Suh, is betrayed and left for dead until a second chance brings him back years before the relics. Fueled by fury and future knowledge, he sets out to raid each tomb before they arise. (Source: Crunchyroll)', null, 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx184356-SlFIstXUXJYP.png', 'TV', 'RELEASING', null, 12, 23, 66, 66000, 'PG-13', 'HD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (209983, 209983, 'hell-mode-the-hardcore-gamer-dominates-in-another-world-with-garbage-balancing-s', 'HELL MODE: The Hardcore Gamer Dominates in Another World with Garbage Balancing Season 2', 'Hell Mode: Yarikomi-zuki no Gamer wa Haisettei no Isekai de Musou Suru 2nd Season', 'The second season of Hell Mode.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/209983-fJysbFB72IM9.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209983-sFOcKyqMufxb.jpg', 'TV', 'RELEASING', 2026, 13, 25, 71, 71000, 'NC-17', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (103303, 103303, 'sparks-of-tomorrow', 'Sparks of Tomorrow', 'Nijusseiki Denki Mokuroku: Eureka Evrika', 'The novel takes place in the summer of 1907, the 40th year of the Meiji era. 15-year-old Inako Momokawa lives in the Fushimi area of Kyoto, and is the second daughter of a sake brewer. Nothing she does ever comes out right, and she receives a scolding from her father every day. Her only relief is the trust she places in her prayers to the gods. One day while at Fushimi Inari shrine, she meets a freewheeling young man named Kihachi Sakamoto. He rejects the gods, and boasts of the incoming age of electricity. The topic of marriage suddenly comes up in Inako''s household. Her father is one-sidedly making all the decisions for her, and Inako is about to give up hope. It is then that Kihachi draws out Inako''s true feelings of wanting to run away from her family. The only way to stop her marriage is to find an unusual book called the "Electricity Catalog." The book is a prediction book about electricity that Kihachi wrote when he was a child, but his older brother Seiroku took the book, and its current whereabouts are unknown. Inako and Kihachi together go in search of the book across Kyoto and Shiga prefectures. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103303-K73aVOqkCPqL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103303-IF43hFJPPv2Y.png', 'TV', 'RELEASING', 2026, 13, 25, 76, 76000, 'NC-17', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (210031, 210031, 'you-and-i-are-polar-opposites-season-2', 'You and I Are Polar Opposites Season 2', 'Seihantai na Kimi to Boku 2nd Season', 'Six months have passed since the polar opposite classmates Miyu Suzuki and Yuusuke Tani started dating. Through spending time together along with their friends from school, the two have been happier than ever. As the year nears its end, the new couple plans to celebrate Christmas and the New Year together, making memories for years to come. Meanwhile, Miyu and Yuusuke''s friends Shuuji Taira and Kentarou Yamada are puzzled by their own situations. Due to his bad experiences in middle school, Taira still overthinks everything around him, especially after his classmate Shino Azuma began giving him more attention. Simultaneously, the usually energetic and outspoken Yamada finds it difficult to find the perfect time to confess his feelings to his shy schoolmate Natsumi Nishi. Despite everyone''s differences, they continue enjoying their adolescence together and find their own ways to turn the winter break into a cherished memory. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/210031-M4bt0rAmWk5Q.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx210031-TppgcHZh46LY.jpg', 'TV', 'RELEASING', 2026, 13, 24, 82, 82000, 'PG-13', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (197754, 197754, 'liar-game', 'LIAR GAME', 'LIAR GAME', 'Wishing she would live up to the ideal, Kanzaki Nao''s father named her thusly for “honesty”. Nao has more than lived up to her father''s wishes--even exceeding them and earning the label of "a foolishly honest girl". This makes Nao the least qualified candidate for the high stakes ''Liar Game'', where winning requires deceiving the opponent out of their money and losing means receiving massive debt. However, that doesn''t stop a box containing a hundred million yen in cash and a card informing her of her participation in the game from arriving at her doorstep, nor does it stop her from being promptly tricked out of the entire sum of money. Upon hearing that a genius swindler, responsible for the bankruptcy of a major corporation, is being released from jail, Nao goes to the swindler, Shinichi Akiyama, to enlist his help. With that, the two are drawn into the dark, greed-filled, and deceptive world of the Liar Game.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197754-cMWxeRdhYrFW.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx197754-Q5KqcUhIdypp.png', 'TV', 'RELEASING', 2026, 26, 24, 62, 62000, 'G', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20605, 20605, 'tokyo-ghoul', 'Tokyo Ghoul', 'Tokyo Ghoul', 'The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20605-RCJ7M71zLmrh.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b20605-k665mVkSug8D.jpg', 'TV', 'FINISHED', 2014, 12, 24, 76, 76000, 'PG', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20613, 20613, 'akame-ga-kill', 'Akame ga Kill!', 'Akame ga Kill!', 'In a land where corruption rules and a ruthless Prime Minister has turned the puppet Emperor''s armies of soldiers, assassins and secret police against the people, only one force dares to stand against them: Night Raid, an elite team of relentless killers, each equipped with an Imperial Arm - legendary weapons with unique and incredible powers created in the distant past. Rescued from a fate worse than death by Night Raid, young Tatsumi is offered the chance to join their lethal ranks… but it''s a deadly choice, as few can master an Imperial Arm and even fewer survive when two Arms go against each other in combat. The battle is on, and only the strongest will make it out alive. (Source: Sentai Filmworks)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20613-CoEQF4qKiWDX.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20613-HXHpec4bemk5.jpg', 'TV', 'FINISHED', 2014, 24, 24, 73, 73000, 'NC-17', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20623, 20623, 'parasyte-the-maxim', 'Parasyte -the maxim-', 'Kiseijuu: Sei no Kakuritsu', 'They arrive in silence and darkness. They descend from the skies. They have a hunger for human flesh. They are everywhere. They are parasites, alien creatures who must invade–and take control of–a human host to survive. And once they have infected their victims, they can assume any deadly form they choose: monsters with giant teeth, winged demons, creatures with blades for hands. But most have chosen to conceal their lethal purpose behind ordinary human faces. So no one knows their secret–except an ordinary high school student. Shin is battling for control of his own body against an alien parasite, but can he find a way to warn humanity of the horrors to come? (Source: Del Rey)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20623-xb9PPf8rGOsG.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20623-dUARfggnNDOe.jpg', 'TV', 'FINISHED', 2014, 24, 24, 81, 81000, 'NC-17', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (10620, 10620, 'the-future-diary', 'The Future Diary', 'Mirai Nikki', 'This psychological thriller, based on the manga written and illustrated by Sakae Esuno, is about Yuki, a loner who''s not very good with people. He prefers to write a diary on his cell phone and talk to his imaginary friend, Deus Ex Machina &ndash; The God of Time and Space. However, Yuki soon learns that Deus is more than a figment of his imagination when he makes Yuki participate in a battle royale with eleven others. The contestants are given special diaries that can predict the future, each diary possessing unique features that give it both advantages and disadvantages. Within the next 90 days, the contestants must try to survive until there is only one left standing. The winner will become the new God of Time and Space. (Source: FUNimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10620-CsZ2FFSbGpqV.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10620-dUZeNej0W4QN.png', 'TV', 'FINISHED', 2011, 26, 23, 69, 69000, 'PG', 'HD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20850, 20850, 'tokyo-ghoul-a', 'Tokyo Ghoul √A', 'Tokyo Ghoul √A', 'The ghouls of Anteiku invaded the Aogiri''s site in order to rescue Ken Kaneki who is being tortured. Due to provocation, he unleashed greater power enough to defeat Yamori. To become stronger, he decided to join Aogiri and left Anteiku. Ghoul investigators also making their moves by collecting information about the eye-patched ghoul - Ken Kaneki. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20850-YjtRXQkNl0xz.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20850-glDf9EMKeCwe.jpg', 'TV', 'FINISHED', 2015, 12, 24, 67, 67000, 'PG', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (97986, 97986, 'made-in-abyss', 'Made in Abyss', 'Made in Abyss', 'The "Abyss" is the last unexplored place in the world. Strange and wonderful creatures roam within, and it is full of precious relics that present humans can''t recreate. Those that dare to explore the depths are known as "Cave Raiders." An orphan girl named Riko lives on the rim. Her dream is to become a Cave Raider like her mother and solve the mysteries of the cave system. One day, Riko starts exploring the caves and discovers a robot who resembles a human boy. (Source: Anime News Network, edited) Note: The last episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97986-C55UnbJKB7ZF.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97986-TQ7dCgbS3y5s.jpg', 'TV', 'FINISHED', 2017, 13, 25, 84, 84000, 'PG-13', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (11111, 11111, 'another', 'Another', 'Another', 'When Kouichi Sakakibara transfers to a new school, he senses a frightening atmosphere in his new class, a secret none of them will talk about. At the center is the beautiful Mei Misaki. Kouichi is immediately drawn to her mysterious aura, but he begins to realize that no one else in the class is aware of her presence. Soon after his arrival, what is known as the Calamity begins, and it claims the lives of many students. (Source: Sentai Filmworks)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11111.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11111-gvvE5bBYsyFo.png', 'TV', 'FINISHED', 2012, 12, 24, 71, 71000, 'PG-13', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (98460, 98460, 'devilman-crybaby', 'Devilman Crybaby', 'DEVILMAN crybaby', 'The protagonist Akira Fudou learns from his best friend, Ryou Asuka, that an ancient race of demons has returned to take back the world from humans. Ryou tells Akira that the only way to defeat the demons is to incorporate their supernatural powers, and suggests that he unite with a demon himself. Akira succeeds in transforming into Devilman, who possesses both the powers of a demon and the soul of a human. The battle of Devilman and Akira Fudou begins. (Source: Netflix) Note: New Devilman project marking Go Nagai''s 50th anniversary as a creator.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98460-PwSHquwVu89n.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98460-bLtH2c3jd6sV.png', 'ONA', 'FINISHED', 2018, 10, 25, 76, 76000, 'PG', 'HD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (19, 19, 'monster', 'Monster', 'MONSTER', 'Dr. Kenzo Tenma is a renowned Japanese brain surgeon working at a leading hospital in Germany. One night, Dr. Tenma risks his reputation and career to save the life of a critically wounded young boy over that of the town mayor who had been planning to support the hospital financially. A string of mysterious murders begin to occur soon after the operation, and Dr. Tenma emerges as the primary suspect despite no incriminating evidence. A doctor is taught to believe that all life is equal; however, when another series of murders occur in the surgeon''s vicinity, Dr. Tenma''s beliefs are shaken as his actions that night are shown to have much broader consequences than he could have imagined. Leaving behind his life as a surgeon he embarks on a journey across the country to unravel the mystery of the boy he saved.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19-kJhwsB0Z97tL.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx19-gtMC64182sm4.jpg', 'TV', 'FINISHED', 2004, 74, 24, 88, 88000, 'G', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (108725, 108725, 'the-promised-neverland-season-2', 'The Promised Neverland Season 2', 'Yakusoku no Neverland 2', 'Fifteen children escape Grace Field House, a false paradise, hoping for a chance at freedom. Instead, they encounter plants and animals they have never before seen, and are chased by demons. The outside world is so beautiful, and yet is almost too cruel to face. Even so, the children refuse to give up. They are guided in their search for better lives only by a message from Minerva and a pen Norman left behind in order to fulfill their promise to return to the House to save those of their family who are still trapped within. (Source: Aniplex of America) Note: Episode 1 streamed early on Amazon Prime on Jan 7, 2021. The regular TV broadcast started on Jan 8, 2021.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108725-lg940Urvxzfu.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108725-ZKivuyr4Jtc9.jpg', 'TV', 'FINISHED', 2021, 11, 23, 51, 51000, 'PG', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (140960, 140960, 'spy-x-family', 'SPY x FAMILY', 'SPY×FAMILY', 'Everyone has a part of themselves they cannot show to anyone else. At a time when all nations of the world were involved in a fierce war of information happening behind closed doors, Ostania and Westalis had been in a state of cold war against one another for decades. The Westalis Intelligence Services'' Eastern-Focused Division (WISE) sends their most talented spy, "Twilight," on a top-secret mission to investigate the movements of Donovan Desmond, the chairman of Ostania''s National Unity Party, who is threatening peace efforts between the two nations. This mission is known as "Operation Strix." It consists of "putting together a family in one week in order to infiltrate social gatherings organized by the elite school that Desmond''s son attends." "Twilight" takes on the identity of psychiatrist Loid Forger and starts looking for family members. But Anya, the daughter he adopts, turns out to have the ability to read people''s minds, while his wife, Yor, is an assassin! With it being in each of their own interests to keep these facts hidden, they start living together while concealing their true identities from one another. World peace is now in the hands of this brand-new family as they embark on an adventure full of surprises. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140960-Z7xSvkRxHKfj.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140960-Kb6R5nYQfjmP.jpg', 'TV', 'FINISHED', 2022, 12, 24, 83, 83000, 'PG', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (101921, 101921, 'kaguya-sama-love-is-war', 'Kaguya-sama: Love is War', 'Kaguya-sama wa Kokurasetai: Tensaitachi no Renai Zunousen', 'Known for being both brilliant and powerful, Miyuki Shirogane and Kaguya Shinomiya lead the illustrious Shuchiin Academy as near equals. And everyone thinks they’d make a great couple. Pride and arrogance are in ample supply, so the only logical move is to trick the other into instigating a date! Who will come out on top in this psychological war where the first move is the only one that matters? (Source: Aniplex)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101921-GgvvFhlNhzlF.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101921-ufrjLzhSz7L1.jpg', 'TV', 'FINISHED', 2019, 12, 24, 83, 83000, 'PG-13', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21827, 21827, 'violet-evergarden', 'Violet Evergarden', 'Violet Evergarden', 'A certain point in time, in the continent of Telesis. The great war which divided the continent into North and South has ended after four years, and the people are welcoming a new generation. Violet Evergarden, a young girl formerly known as “the weapon”, has left the battlefield to start a new life at CH Postal Service. There, she is deeply moved by the work of “Auto Memories Dolls”, who carry people''s thoughts and convert them into words. Violet begins her journey as an Auto Memories Doll, and comes face to face with various people''s emotions and differing shapes of love. There are words Violet heard on the battlefield, which she cannot forget. These words were given to her by someone she holds dear, more than anyone else. She does not yet know their meaning but she searches to find it. (Source: Anime News Network)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21827-ROucgYiiiSpR.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21827-ubzq619ZA2E9.png', 'TV', 'FINISHED', 2018, 13, 24, 85, 85000, 'R', 'SUB', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (4224, 4224, 'toradora', 'Toradora!', 'Toradora!', 'Ryuuji Takasu is a gentle high school student with a love for housework; but in contrast to his kind nature, he has an intimidating face that often gets him labeled as a delinquent. On the other hand is Taiga Aisaka, a small, doll-like student, who is anything but a cute and fragile girl. Equipped with a wooden katana and feisty personality, Taiga is known throughout the school as the "Palmtop Tiger." One day, an embarrassing mistake causes the two students to cross paths. Ryuuji discovers that Taiga actually has a sweet side: she has a crush on the popular vice president, Yuusaku Kitamura, who happens to be his best friend. But things only get crazier when Ryuuji reveals that he has a crush on Minori Kushieda—Taiga''s best friend! Toradora! is a romantic comedy that follows this odd duo as they embark on a quest to help each other with their respective crushes, forming an unlikely alliance in the process.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4224-iPUOHdMde27j.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4224-PXVMBLNwy2aF.jpg', 'TV', 'FINISHED', 2008, 25, 24, 77, 77000, 'G', 'HD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (124080, 124080, 'horimiya', 'Horimiya', 'Horimiya', 'A secret life is the one thing they have in common. At school, Hori is a prim and perfect social butterfly, but the truth is she''s a brash homebody. Meanwhile, under a gloomy facade, Miyamura hides a gentle heart, along with piercings and tattoos. In a chance meeting, they both reveal a side they''ve never shown. Could this blossom into something new? (Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124080-ARyLAHHgikRq.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx124080-3i22mRVPBS0T.jpg', 'TV', 'FINISHED', 2021, 13, 24, 81, 81000, 'PG', 'HD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (101338, 101338, 'mob-psycho-100-ii', 'Mob Psycho 100 II', 'Mob Psycho 100 II', 'Kageyama is an ordinary 8th grader who just wants to live a normal life. Although he can disappear in the crowd in a flash, he was actually the most powerful psychic. The lives of those around Mob and his numerous feelings that softly piles up for the eventual explosion. The mysterious group "Claw" stands before him once again. In the midst of his youthful days, where will his roaring heart take him!? (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101338-Rl54Qhx71dUq.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101338-rokVscjRYzdP.jpg', 'TV', 'FINISHED', 2019, 13, 24, 87, 87000, 'NC-17', 'FHD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (112641, 112641, 'kaguya-sama-love-is-war-1', 'Kaguya-sama: Love is War?', 'Kaguya-sama wa Kokurasetai?: Tensaitachi no Renai Zunousen', 'After a slow but eventful summer vacation, Shuchiin Academy''s second term is now starting in full force. As August transitions into September, Miyuki Shirogane''s birthday looms ever closer, leaving Kaguya Shinomiya in a serious predicament as to how to celebrate it. Furthermore, the tenure of the school''s 67th student council is coming to an end. Due to the council members being in different classes, the only time Kaguya and Miyuki have to be together will soon disappear, putting all of their cunning plans at risk. A long and difficult election that will decide the fate of the new student council awaits, as multiple challengers fight for the coveted title of president. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112641-mKZe0zng0ndV.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112641-zoGC8d6FaPXU.jpg', 'TV', 'FINISHED', 2020, 12, 25, 85, 85000, 'PG-13', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (132405, 132405, 'my-dress-up-darling', 'My Dress-Up Darling', 'Sono Bisque Doll wa Koi wo Suru', 'High schooler Wakana Gojou cares about one thing: making Hina dolls. With nobody to share his obsession, he has trouble finding friends—or even holding conversation. But after the school’s most popular girl, Marin Kitagawa, reveals a secret of her own, he discovers a new purpose for his sewing skills. Together, they’ll make her cosplay dreams come true! (Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/132405-LnPQaqaksEpN.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx132405-qP7FQYGmNI3d.jpg', 'TV', 'FINISHED', 2022, 12, 24, 80, 80000, 'PG', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (15809, 15809, 'the-devil-is-a-part-timer', 'The Devil is a Part-Timer!', 'Hataraku Maou-sama!', 'Devil King Sadao is only one step away from conquering the world when he is beaten by Hero Emilia and forced to drift to the other world: modern-day Tokyo. As "conquering the world" are the only skills the Devil King possesses&mdash;and are obviously unnecessary in his new situation&mdash;he must work as a freeter to pay for his living expenses!', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15809-kX2mopBGBw6g.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx15809-ECv3HyOYJKrk.jpg', 'TV', 'FINISHED', 2013, 13, 24, 75, 75000, 'G', '4K', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (114129, 114129, 'gintama-the-very-final', 'Gintama: THE VERY FINAL', 'Gintama: THE FINAL', 'Two years have passed following the Tendoshuu''s invasion of the O-Edo Central Terminal. Since then, the Yorozuya have gone their separate ways. Foreseeing Utsuro''s return, Gintoki Sakata begins surveying Earth''s ley lines for traces of the other man''s Altana. After an encounter with the remnants of the Tendoshuu—who continue to press on in search of immortality—Gintoki returns to Edo. Later, the regrouped Shinsengumi and Yorozuya begin an attack on the occupied Central Terminal. With the Altana harvested by the wreckage of the Tendoshuu''s ship in danger of detonating, the Yorozuya and their allies fight their enemies while the safety of Edo—and the rest of the world—hangs in the balance. Fulfilling the wishes of their teacher, Shouyou Yoshida''s former students unite and relive their pasts one final time in an attempt to save their futures.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/114129-ZsLDkdwaYeJY.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114129-RLgSuh6YbeYx.jpg', 'MOVIE', 'FINISHED', 2021, 1, 104, 91, 91000, 'G', '4K', false, false, false, true, 1);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (154587, 154587, 'frieren-beyond-journey-s-end', 'Frieren: Beyond Journey’s End', 'Sousou no Frieren', 'The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure… (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154587-ivXNJ23SM1xB.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154587-qQTzQnEJJ3oB.jpg', 'TV', 'FINISHED', 2023, 28, 24, 91, 91000, 'R', 'SUB', false, false, false, true, 2);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20996, 20996, 'gintama-season-3', 'Gintama Season 3', 'Gintama°', 'Gintoki, Shinpachi, and Kagura return as the fun-loving but broke members of the Yorozuya team! Living in an alternate-reality Edo, where swords are prohibited and alien overlords have conquered Japan, they try to thrive on doing whatever work they can get their hands on. However, Shinpachi and Kagura still haven''t been paid... Does Gin-chan really spend all that cash playing pachinko? Meanwhile, when Gintoki drunkenly staggers home one night, an alien spaceship crashes nearby. A fatally injured crew member emerges from the ship and gives Gintoki a strange, clock-shaped device, warning him that it is incredibly powerful and must be safeguarded. Mistaking it for his alarm clock, Gintoki proceeds to smash the device the next morning and suddenly discovers that the world outside his apartment has come to a standstill. With Kagura and Shinpachi at his side, he sets off to get the device fixed; though, as usual, nothing is ever that simple for the Yorozuya team. Filled with tongue-in-cheek humor and moments of heartfelt emotion, Gintama''s fourth season finds Gintoki and his friends facing both their most hilarious misadventures and most dangerous crises yet. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20996-gaNJKtjmy3Pf.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20996-kBEGEGdeK1r7.jpg', 'TV', 'FINISHED', 2015, 51, 24, 90, 90000, 'PG-13', 'HD', true, false, false, true, 3);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (171627, 171627, 'chainsaw-man-the-movie-reze-arc', 'Chainsaw Man – The Movie: Reze Arc', 'Chainsaw Man: Reze-hen', 'Denji became “Chainsaw Man”, a boy with a devil’s heart, and is now part of Special Division 4’s devil hunters. After a date with Makima, the woman of his dreams, Denji takes shelter from the rain. There he meets Reze, a girl who works in a café. (Source: MAPPA CHANNEL)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/171627-7esVHhgw69rn.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171627-ZN9D7P46yHnw.png', 'MOVIE', 'FINISHED', 2025, 1, 100, 90, 90000, 'R', 'SUB', false, false, false, true, 5);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (185874, 185874, 'bleach-thousand-year-blood-war-the-calamity', 'BLEACH: Thousand-Year Blood War - The Calamity', 'BLEACH: Sennen Kessen-hen - Kashin-tan', 'Destruction looms at the end of the Thousand-Year Blood War between the Soul Reapers and Quincies… as the death of the Soul King mirrors the collapse of the Three Worlds, distortions and omens of destruction start to appear in all realms. Fierce battles erupt throughout the Wahr Welt between the Thirteen Court Guard Squads and the Royal Guard. Ichigo learns about Uryuu''s true intentions and renews his determination to protect the world together, as friends who trust each other. Yhwach has surpassed even his own ability, The Almighty... The fierce battle for the survival of the Three Worlds approaches its end. Beyond the chaos of calamity, what lies in wait—despair or hope? (Source: VIZ Media, edited)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185874-IdGyh1EBG91I.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185874-aU3e6tBT6wwA.jpg', 'TV', 'RELEASING', 2026, 10, null, 90, 90000, 'G', 'FHD', false, false, false, true, 7);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (182469, 182469, 'one-piece-fan-letter', 'ONE PIECE FAN LETTER', 'ONE PIECE FAN LETTER', 'Two years after the Paramount War, the Straw Hats are about to reunite on the Sabaody Archipelago. At the same time, a girl who is head over heels for Nami is trying to hand a fan letter to her before the group leaves the island. (Source: Crunchyroll) Note: This work commemorates the 25th anniversary of the ONE PIECE anime through an animated adaptation of the "ONE PIECE novel Mugiwara Stories" light novel.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182469-obNr7bznMzN7.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx182469-JQ808NBPxmgn.jpg', 'SPECIAL', 'FINISHED', 2024, 1, 25, 89, 89000, 'G', '4K', false, false, false, true, 9);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (124194, 124194, 'fruits-basket-the-final-season', 'Fruits Basket The Final Season', 'Fruits Basket: The Final', 'After last season’s revelations, the Soma family moves forward, but the emotional chains that bind them are not easily broken. Unable to admit why she wants the cure, Tohru wrestles with the truth, aware that time is running out for someone close. And a secret still lurks that could break another’s heart. But hope is not lost—a clue to the curse is found. Could their imprisonment’s end be near? (Source: Funimation) Note: This season premiered on Funimation and AnimeLab on March 20, 2021. The Japanese broadcast started two weeks later on April 6, 2021.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124194-IB2X2IdALUYB.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx124194-TJlqMMR7BGn9.jpg', 'TV', 'FINISHED', 2021, 13, 24, 89, 89000, 'G', 'FHD', false, false, false, true, 10);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (197474, 197474, 'gintama-the-movie-2026-yoshiwara-in-flames', 'Gintama the Movie 2026: Yoshiwara in Flames', 'Shin Gintama Movie: Yoshiwara Daienjou', 'Movie remake of the Yoshiwara Enjou arc. Upon meeting a young boy named Haruta who makes a living as a pickpocket, Gintoki discovers that he is pickpocketing out of a desire to meet his long-lost mother, Hiwa, Yoshiwara''s number one courtesan. Gintoki and his friends venture to Yoshiwara to fulfill Haruta''s wish, but standing in their way is Housen, the Night King who rules Yoshiwara. Note: This anime was announced at the "Gintama Multiverse Festival," an event held on August 16th, as part of the "Gintama 20th Anniversary Project." This movie features volumes 25 and 26 of the manga, and the TV anime series spans eight episodes, from episodes 139 to 146.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197474-dcJmLSLc3g10.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx197474-jTeY1G9gtD8i.jpg', 'MOVIE', 'FINISHED', 2026, 1, 124, 87, 87000, 'G', 'FHD', true, false, false, true, 4);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (15335, 15335, 'gintama-the-final-chapter-be-forever-yorozuya', 'Gintama: The Final Chapter - Be Forever Yorozuya', 'Gintama: Kanketsu-hen - Yorozuya yo Eien Nare', 'When Gintoki apprehends a movie pirate at a premiere, he checks the camera''s footage and finds himself transported to a bleak, post-apocalyptic version of Edo, where a mysterious epidemic called the "White Plague" has ravished the world''s population. It turns out that the movie pirate wasn''t a pirate after all—it was an android time machine, and Gintoki has been hurtled five years into the future! Shinpachi and Kagura, his Yorozuya cohorts, have had a falling out and are now battle-hardened solo vigilantes and he himself has been missing for years, disappearing without a trace after scribbling a strange message in his journal. Setting out in the disguise given to him by the android time machine, Gintoki haphazardly reunites the Yorozuya team to investigate the White Plague, and soon discovers that the key to saving the future lies in the darkness of his own past. Determined to confront a powerful foe, he makes an important discovery—with a ragtag band of friends and allies at his side, he doesn''t have to fight alone. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15335-uARkRgyx8adp.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx15335-QjijwChGTBs0.png', 'MOVIE', 'FINISHED', 2013, 1, 110, 87, 87000, 'PG', 'SUB', true, false, false, true, 5);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21400, 21400, 'kizumonogatari-part-3-reiketsu', 'Kizumonogatari Part 3: Reiketsu', 'Kizumonogatari III: Reiketsu-hen', 'First season of the Monogatari Series, part 4/6. Contains the arc Koyomi Vamp from the Kizumonogatari light novel. With help from Meme Oshino, the apparition specialist, Koyomi defeats the three powerful vampire hunters: Dramaturgy, Episode and Guillotinecutter. Koyomi takes back all the limbs of Kiss-Shot Acerola-Orion Heart-Under-Blade in order to become a human again. But, when he returns to Kiss-Shot, she reveals to him the cold truth of what it means to be a vampire—a creature of the night. Unable to take back what he has done, Koyomi feels nothing but regret and can only deny his dreadful fate. While Koyomi is struggling to face reality, his “friend” Tsubasa Hanekawa comes to him with a certain plan… (Source: Aniplex)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21400-5zcYUeVBptdG.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21400-38ykNo3j4xXo.png', 'MOVIE', 'FINISHED', 2017, 1, 82, 87, 87000, 'PG', 'HD', true, false, false, true, 6);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (103047, 103047, 'violet-evergarden-the-movie', 'Violet Evergarden: the Movie', 'Violet Evergarden Movie', 'While writing other people’s emotions, she may have neglected her own. Violet Evergarden, the child soldier turned Auto Memory Doll, writes letters that evoke the words her clients can’t. But when a terminally ill boy requests her services for his family, her own feelings about love and loss resurface. Now she must confront her past and the death of the Major. (Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103047-Tjvsh5w1XZP4.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103047-odblDHHEdehK.jpg', 'MOVIE', 'FINISHED', 2020, 1, 140, 87, 87000, 'R', 'SUB', false, false, false, true, 7);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (113024, 113024, 'revue-starlight-the-movie', 'Revue Starlight: The Movie', 'Shoujo☆Kageki Revue Starlight Movie', 'The stage emulates life and compresses it, setting free skills learned over lifetimes in brief but dazzling displays for the amusement and judgment of others. For the performers, it is the ultimate risk, and some will rise while others must fall. Nowhere is this truer than at the Seisho Music Academy, where music, dance and real weapons all come into play in the creation of the next great Star. Karen and Hikari’s destinies have been linked since a childhood promise, but their journeys here have taken very different paths. Now, after Hikari leaves, Karen must discover who she is without her opposite, while Hikari must rediscover her own course. (Source: Sentai Filmworks)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113024-gjxwISIts05f.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113024-OdzOh0OKFPTN.png', 'MOVIE', 'FINISHED', 2021, 1, 120, 87, 87000, 'G', 'HD', true, false, false, true, 8);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (128207, 128207, 'the-first-slam-dunk', 'THE FIRST SLAM DUNK', 'THE FIRST SLAM DUNK', 'Shohoku''s “speedster” and point guard, Ryota Miyagi, always plays with brains and lightning speed, running circles around his opponents while feigning composure. Born and raised in Okinawa, Ryota had a brother who was three years older. Following in the footsteps of his older brother, who was a famous local player from a young age, Ryota also became addicted to basketball. In his second year of high school, Ryota plays with the Shohoku High School basketball team along with Sakuragi, Rukawa, Akagi, and Mitsui as they take the stage at the Inter-High School National Championship. And now, they are on the brink of challenging the reigning champions, Sannoh Kogyo High School. (Source: GKIDS)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/128207-NogeWbSs2SpJ.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx128207-SWpfVJMRfQ9X.jpg', 'MOVIE', 'FINISHED', 2022, 1, 124, 87, 87000, 'R', 'SUB', true, false, false, true, 9);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (172420, 172420, 'umamusume-pretty-derby-beginning-of-a-new-era', 'Umamusume: Pretty Derby - Beginning of a New Era', 'Uma Musume: Pretty Derby - Shin Jidai no Tobira', 'REACH OUT AND GRASP GREATNESS. Jungle Pocket, known to her close friends as "Pokke," is a free-spirited Umamusume who has proven her dominance in the freestyle racing scene. Overwhelmed by Fuji Kiseki''s majestic performance at a graded Twinkle Series race, she resolves to take on the Twinkle Series herself. Shortly after joining the Umamusume training school Tracen Academy, Pokke comes under the wing of Tanabe, a veteran trainer who fostered Fuji Kiseki''s talent. Together, they aspire to dominate the Triple Crown series, a set of three races that can only be attempted once in a lifetime. Awaiting them are formidable rivals of Pokke''s generation, whose talents surpass even her own. There''s Dantsu Flame, whose diligence and determination to win are second to none; Manhattan Cafe, who chases the shadowy silhouette of a "friend" that only she can see; and Agnes Tachyon, a veritable mad scientist seeking to push the very boundaries of what is possible for Umamusume. These four runners take to the track with their very pride, spirit, and souls on the line. Past the finish of their epic clash is a door waiting to be opened—one that leads to the beginning of a new era. "It doesn''t matter who stands in my way! I''m gonna be the greatest!" (Source: Umamusume: Pretty Derby - Beginning of a New Era Site)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/172420-QVRFOAha7oy5.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx172420-4LjhmwpNMHti.jpg', 'MOVIE', 'FINISHED', 2024, 1, 108, 87, 87000, 'PG', 'HD', true, false, false, true, 10);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (16498, 16498, 'attack-on-titan', 'Attack on Titan', 'Shingeki no Kyojin', 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans. Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind. (Source: MangaHelpers)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16498-8jpFCOcDmneX.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16498-buvcRTBx4NSm.jpg', 'TV', 'FINISHED', 2013, 25, 24, 85, 85000, 'NC-17', 'FHD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (101922, 101922, 'demon-slayer-kimetsu-no-yaiba', 'Demon Slayer: Kimetsu no Yaiba', 'Kimetsu no Yaiba', 'It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family. (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101922-33MtJGsUSxga.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101922-WBsBl0ClmgYL.jpg', 'TV', 'FINISHED', 2019, 26, 24, 82, 82000, 'R', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (113415, 113415, 'jujutsu-kaisen', 'JUJUTSU KAISEN', 'Jujutsu Kaisen', 'A boy fights... for "the right death." Hardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse. Itadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back. (Source: Crunchyroll) Note: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113415-jQBSkxWAAk83.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113415-LHBAeoZDIsnF.jpg', 'TV', 'FINISHED', 2020, 24, 24, 84, 84000, 'PG', 'SUB', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21459, 21459, 'my-hero-academia', 'My Hero Academia', 'Boku no Hero Academia', 'What would the world be like if 80 percent of the population manifested extraordinary superpowers called “Quirks” at age four? Heroes and villains would be battling it out everywhere! Becoming a hero would mean learning to use your power, but where would you go to study? U.A. High''s Hero Program of course! But what would you do if you were one of the 20 percent who were born Quirkless? Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn''t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all gives him a chance to change his destiny… (Source: VIZ Media)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21459-yeVkolGKdGUV.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21459-nYh85uj2Fuwr.jpg', 'TV', 'FINISHED', 2016, 13, 24, 76, 76000, 'G', 'SUB', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (11061, 11061, 'hunter-x-hunter-2011', 'Hunter x Hunter (2011)', 'HUNTER×HUNTER (2011)', 'A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him. After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11061-8WkkTZ6duKpq.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11061-y5gsT1hoHuHw.png', 'TV', 'FINISHED', 2011, 148, 24, 89, 89000, 'PG-13', '4K', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (21087, 21087, 'one-punch-man', 'One-Punch Man', 'One Punch Man', 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch. The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21087-sHb9zUZFsHe1.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21087-B5DHjqZ3kW4b.jpg', 'TV', 'FINISHED', 2015, 12, 24, 82, 82000, 'R', 'SUB', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20958, 20958, 'attack-on-titan-season-2', 'Attack on Titan Season 2', 'Shingeki no Kyojin Season 2', 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues! (Source: Funimation)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20958-Y7eQdz9VENBD.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20958-HuFJyr54Mmir.jpg', 'TV', 'FINISHED', 2017, 12, 25, 85, 85000, 'NC-17', 'FHD', false, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (20, 20, 'naruto', 'Naruto', 'NARUTO', 'Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. Shunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. (Source: MAL Rewrite)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20-HHxhPj5JD13a.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20-dE6UHbFFg1A5.jpg', 'TV', 'FINISHED', 2002, 220, 23, 80, 80000, 'PG', 'HD', true, false, false, false, null);
insert into public.anime (id, anilist_id, slug, title, romaji, description, banner_image, cover_image, format, status, season_year, episodes_count, duration, average_score, popularity, age_rating, quality, is_dub, is_new, is_trending, is_top, top_position) values (11757, 11757, 'sword-art-online', 'Sword Art Online', 'Sword Art Online', 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now... (Source: Crunchyroll)', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11757-TlEEV9weG4Ag.jpg', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11757-SxYDUzdr9rh2.jpg', 'TV', 'FINISHED', 2012, 25, 23, 70, 70000, 'R', '4K', false, false, false, false, null);
